previewCss:
.darma-loader-darma-b14-diff-lines { --accent: var(--loader-color, #22c55e); --accent-2: var(--loader-secondary-color, #ef4444); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .8); display: flex; flex-direction: column; justify-content: space-between; padding: 7%; border-radius: 5px; background: #0b1220; box-shadow: inset 0 0 0 2px #24334d; }
.darma-loader-darma-b14-diff-lines span { position: relative; height: 11%; border-radius: 2px; animation: darma-loader-darma-b14-diff-lines-diff-in calc(var(--loader-speed, 1s) * 2.8) ease-out infinite; }
.darma-loader-darma-b14-diff-lines span:nth-child(odd) { background: var(--accent); }
.darma-loader-darma-b14-diff-lines span:nth-child(even) { background: var(--accent-2); }
.darma-loader-darma-b14-diff-lines span::before { content: ''; position: absolute; top: 22%; left: -6%; width: 3.5%; height: 56%; border-radius: 1px; background: rgba(255, 255, 255, .45); }
.darma-loader-darma-b14-diff-lines span:nth-child(1) { --w: 84%; }
.darma-loader-darma-b14-diff-lines span:nth-child(2) { --w: 62%; animation-delay: calc(var(--loader-speed, 1s) * .16); }
.darma-loader-darma-b14-diff-lines span:nth-child(3) { --w: 94%; animation-delay: calc(var(--loader-speed, 1s) * .32); }
.darma-loader-darma-b14-diff-lines span:nth-child(4) { --w: 48%; animation-delay: calc(var(--loader-speed, 1s) * .48); }
.darma-loader-darma-b14-diff-lines span:nth-child(5) { --w: 76%; animation-delay: calc(var(--loader-speed, 1s) * .64); }
.darma-loader-darma-b14-diff-lines span:nth-child(6) { --w: 58%; animation-delay: calc(var(--loader-speed, 1s) * .8); }
@keyframes darma-loader-darma-b14-diff-lines-diff-in { 0% { opacity: 0; width: 0; } 12% { opacity: 1; } 36% { width: var(--w); } 84% { width: var(--w); } 96%, 100% { opacity: 0; width: 0; } }

